mapper.select:
SELECT FROM users WHERE status = 1
AND id != #{excludeUserId}
AND (username LIKE CONCAT('%', #{keyword}, '%') OR nickname LIKE CONCAT('%', #{keyword}, '%')) ORDER BY id ASC LIMIT #{limit}

mapper.update:
UPDATE users
SET nickname = #{nickname},
    bio = #{bio},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE users
SET role = #{role},
    updated_at = #{updatedAt}
WHERE id = #{id}
